        "texto": "Para um texto de extensão média (20-30 linhas, padrão comum em concursos), a proporção recomendada é: introdução mais enxuta (cerca de 15-20% do texto), desenvolvimento como o núcleo do texto (60-70%, dividido em 2 parágrafos), e conclusão objetiva (15-20%) — desequilibrar muito essa proporção (introdução longa demais, conclusão apressada) prejudica a impressão de organização do texto."
