    "corpo": [
      "Tese é a posição central que o texto vai defender diante do tema proposto — precisa ser específica o suficiente para orientar todo o desenvolvimento, evitando afirmações vagas ou óbvias demais (como 'a educação é importante', que ninguém discordaria e por isso não gera argumentação real). Uma boa tese apresenta um recorte ou uma causa específica que o texto vai explorar em profundidade.",
      "Argumentos de qualidade combinam diferentes tipos de sustentação: argumento de autoridade (citar posição de especialista, instituição reconhecida ou dado de pesquisa confiável), dado estatístico (números que ilustram a dimensão do problema, sem exagero nem invenção), comparação histórica (mostrar como o tema evoluiu ou como outro contexto lidou com problema semelhante), e causa e consequência (explicar por que o problema existe e o que ele gera, criando uma cadeia lógica clara).",
      "Argumentos fracos incluem: opinião pessoal sem sustentação ('eu acho que'), generalização sem evidência ('todo mundo sabe que'), e repetição da tese com outras palavras (sem realmente acrescentar sustentação nova). O texto de nível avançado evita esses argumentos fracos, priorizando sempre fundamentação concreta e verificável."
    ],
