    "corpo": [
      "Repertório sociocultural é o conjunto de referências (históricas, filosóficas, científicas, legislativas, de outras disciplinas) que o candidato traz para enriquecer e sustentar sua argumentação — não é um enfeite a ser 'encaixado' no texto, mas uma ferramenta que precisa se conectar de forma lógica e explícita ao argumento que está sendo defendido naquele parágrafo específico.",
      "O erro mais comum é usar repertório de forma decorativa: citar um filósofo, uma lei ou um fato histórico sem explicar por que aquela referência sustenta o argumento em questão — o corretor não valoriza apenas 'saber' a referência, mas a capacidade de aplicá-la com pertinência ao tema específico da prova. Uma citação de Hobbes sobre o Estado, por exemplo, só tem valor se o texto explicar a conexão entre a ideia de Hobbes e o argumento sendo construído sobre segurança pública, não apenas mencionar o nome do filósofo.",
      "Um repertório eficiente e versátil para concursos de segurança pública inclui: conceitos já estudados nas matérias jurídicas (princípios constitucionais, direitos humanos, art. 144), dados históricos sobre políticas de segurança pública, exemplos de outros países ou estados que adotaram práticas relevantes, e legislação específica (desde que citada com precisão) — o candidato bem preparado percebe que os módulos de Direito Constitucional, Direitos Humanos e Atualidades, já estudados, são fonte natural de repertório para redações desse tipo de concurso."
    ],
    "pontosChave": [
      "Repertório sociocultural precisa se conectar explicitamente ao argumento, não ser apenas 'encaixado' de forma decorativa.",
      "Citar um filósofo/lei/fato histórico exige explicar a conexão lógica com o argumento específico do parágrafo.",
      "Conteúdo jurídico e de direitos humanos já estudado é fonte natural de repertório para redação de concurso policial."
    ],
