    "title": "Coesão e coerência aplicadas à redação",
    "assunto": "Coesão e coerência textual",
    "tecnica": "Uso de conectivos variados entre parágrafos e dentro deles",
    "competencia": "Aplicar coesão e coerência para garantir progressão lógica entre parágrafos e frases",
