    "corpo": [
      "Proposta de intervenção é a etapa final de muitos formatos de redação (mais cobrada nesse formato específico no ENEM, mas também presente em redações discursivas de concursos que pedem 'soluções' para o problema discutido) — precisa apresentar uma ação concreta para enfrentar o problema levantado ao longo do texto, evitando propostas vagas como 'o governo deveria melhorar a educação', que não dizem como.",
      "Uma proposta completa e bem avaliada geralmente contém cinco elementos: agente (quem vai executar a ação — governo federal, estado, escolas, sociedade civil), ação (o que efetivamente será feito), meio/modo (como a ação será executada, com que instrumento ou mecanismo), finalidade (para quê, qual efeito se espera alcançar) e detalhamento (um elemento adicional que aprofunda algum dos anteriores, mostrando que o candidato pensou na aplicação prática, não só na ideia genérica).",
      "A proposta precisa ser exequível (realista, dentro do que é factível para o agente indicado) e conectada aos argumentos já desenvolvidos no texto (não pode surgir do nada, desconectada de tudo que foi discutido antes) — se o desenvolvimento discutiu falta de coordenação entre polícias, por exemplo, a proposta de intervenção deveria abordar diretamente esse ponto, não migrar para um tema totalmente diferente sem conexão."
    ],
