    "corpo": [
      "Questões discursivas de natureza jurídica, comuns em concursos para cargos com exigência técnica (Delegado, Oficial PM, cargos de investigação), diferem da redação argumentativa comum: pedem a aplicação de conhecimento jurídico específico a um caso concreto apresentado no enunciado, exigindo que o candidato identifique o instituto jurídico aplicável e fundamente sua resposta com base na legislação e, quando pertinente, na jurisprudência.",
      "A estrutura recomendada para esse tipo de resposta segue uma lógica de subsunção: (1) identificar os fatos relevantes do caso apresentado, (2) identificar a norma jurídica aplicável (artigo de lei, princípio constitucional, entendimento consolidado), (3) explicar por que aquela norma se aplica àqueles fatos específicos (a subsunção propriamente dita), e (4) concluir com a resposta objetiva à pergunta feita (qual crime se configura, qual medida cabe, se a conduta é lícita ou não).",
      "Diferente da redação argumentativa livre, aqui não há espaço para opinião pessoal sobre o que 'deveria ser a lei' — a resposta deve refletir o que a lei e a jurisprudência efetivamente estabelecem, com precisão técnica (nomes corretos de institutos, número de lei quando pertinente, ao invés de referências vagas como 'aquela lei que fala sobre...'). Precisão técnica e fundamentação clara pesam mais nesse formato do que estilo literário ou repertório sociocultural amplo."
    ],
