        "respostaEsperada": "Imagine como construir uma casa: introdução é a porta, desenvolvimento são as paredes e conclusão é o acabamento. Neste capítulo, \"Redação discursiva jurídica: estudo de caso e peça técnica\", a ideia principal é: Questões discursivas de natureza jurídica, comuns em concursos para cargos com exigência técnica (Delegado, Oficial PM, cargos de investigação), diferem da redação argumentativa comum: pedem a aplicação de conhecimento jurídico específico a um caso concreto. Para estudar sem travar, guarde primeiro estas palavras-chave: estudo de caso, fundamentação legal, subsunção. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Fato, norma, explicação da subsunção, resposta objetiva — precisão técnica vale mais que estilo ou repertório amplo nesse formato.",
