      "Concursos policiais tendem a repetir um conjunto relativamente previsível de temas de redação, todos já trabalhados de alguma forma nos módulos anteriores desta plataforma: violência urbana e criminalidade organizada, letalidade policial e uso da força, sistema penitenciário e ressocialização, violência doméstica e feminicídio, crimes cibernéticos, tecnologia aplicada à segurança pública, e ética/abuso de autoridade na atividade policial.",
      "Para cada um desses temas, vale a pena ter, previamente pensado (não decorado literalmente, mas estruturado mentalmente), um recorte de tese possível e dois ou três argumentos de sustentação com repertório já conectado — por exemplo, para 'letalidade policial', um recorte possível é discutir a relação entre treinamento inadequado em uso progressivo da força e o aumento de mortes evitáveis em confronto, sustentando com o conteúdo já estudado em Direitos Humanos.",
      "É importante treinar também temas que cruzam segurança pública com outras áreas: tecnologia (uso de câmeras corporais e reconhecimento facial, questões de viés algorítmico), meio ambiente (crimes ambientais, atuação de polícias ambientais), e direitos humanos (grupos vulneráveis, racismo institucional) — a interseção entre temas é cada vez mais comum em provas de nível mais avançado, e o candidato que já percebe essas conexões (como os módulos desta plataforma vêm reforçando ao longo de todo o conteúdo) tem vantagem real na hora de redigir."
