      "Ofício: comunicação externa entre órgãos/autoridades. Memorando: comunicação interna, ágil, entre setores.",
      "Ata registra fielmente reunião, sem parágrafos e sem rasura — correções são feitas por 'em tempo', não apagando o texto."
