      "A revisão final deve seguir uma ordem do geral para o específico, para ser eficiente dentro do tempo limitado de prova: primeiro revise a estrutura (introdução tem tese clara? cada parágrafo de desenvolvimento tem um argumento bem sustentado? a conclusão retoma a tese e, se exigido, traz proposta completa?), depois a coesão/coerência (os parágrafos estão bem conectados? há repetição excessiva ou contradição entre partes do texto?), e só por último os detalhes gramaticais (concordância, ortografia, pontuação).",
      "Reserve um tempo específico da prova exclusivamente para essa revisão — mesmo sob pressão de tempo, um mínimo de 5 a 10 minutos de revisão final costuma valer mais em termos de nota do que continuar escrevendo até o último segundo sem rever nada. Erros de concordância, ortografia e pontuação (já estudados no módulo de Português) são frequentemente penalizados de forma cumulativa, então revisar essa camada final é sempre valioso.",
      "Um checklist prático e rápido para os últimos minutos: (1) a tese está clara desde a introdução? (2) cada parágrafo tem um argumento com fundamentação (não só opinião)? (3) há proposta de intervenção completa, se exigida, com os elementos necessários? (4) o texto respeita a extensão mínima e máxima exigida? (5) há erros óbvios de concordância ou grafia que uma releitura rápida resolveria? Passar por essas cinco perguntas, mesmo rapidamente, reduz significativamente o risco de erros evitáveis na versão final entregue."
